// Standalone design interactions. All revisions, users and operations are illustrative.
// There is deliberately no API client, fetch, authentication or persistence here.
const I=n=>`<svg class="svg" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const B=(label,action,kind='',icon='',extra='')=>`<button class="${kind}" data-action="${action}" ${extra}>${icon?I(icon):''}${label}</button>`;
const rootName='GegevensmodelZZZZ Local Recover';
let view='model',editorState='draft',dock='inspector',prId=18,revision=2,selectedRevision=2,prState='OPEN',prTab='diff',correcting=false,correctionSaved=false,released=false,envFilter='all',selectedFile='gegevens',threadResolved=false;
const environments=[{name:'Integration',type:'test',version:'1.4.0',status:'Succeeded',config:3},{name:'Regression',type:'test',version:'1.3.0',status:'Running',config:2},{name:'Acceptance',type:'test',version:'1.3.0',status:'Uncertain',config:4},{name:'Production EU',type:'production',version:'1.3.0',status:'Blocked',config:5}];
const snapshots={1:{revision:1,hash:'19c73a4',digest:'77ac9821…401b',status:'Changes requested'},2:{revision:2,hash:'4ae7b2c',digest:'9c1f72b4…6f08',status:'In review'}};
function escapeText(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function go(next){view=next;location.hash=next;render();}
function iconLabels(){const labels={'new-root':'New root','toggle-tree':'Toggle project panel','toggle-dock':'Toggle bottom panel','more':'More root actions','undo':'Undo','redo':'Redo','close-modal':'Close dialog','configure-env':'Configure environment'};document.querySelectorAll('button[data-action]').forEach(b=>{if(!b.textContent.trim())b.setAttribute('aria-label',labels[b.dataset.action]||b.dataset.action)});}
function render(){document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===view));document.querySelector('#screen').innerHTML=({model,changes,pulls:pullRequest,releases:releaseList,deployments:environmentPage}[view]||model)();const role=view==='pulls'&&!correcting?'reviewer':view==='deployments'?'administrator':'author';document.querySelector('#identity-label').textContent=role+' Local';document.querySelector('#avatar').textContent=role==='reviewer'?'RL':role==='administrator'?'AD':'AL';document.querySelector('#state-preview').disabled=view!=='model';document.querySelector('#state-preview').value=editorState;document.querySelector('#footer-state').textContent=view==='model'&&editorState==='loading'?'Initializing authorized models':'Design preview · no application changes';iconLabels();}
const treeGroup=(name,rows)=>`<div class="tree-group">${I('down')}${I('folder')}<span title="${name}">${name}</span></div>${rows.map(([name,type,selected])=>`<button class="${selected?'selected':''}" title="${name} · ${type}" data-action="root"><span class="type-icon">${type[0]}</span><span class="label">${name}</span>${selected?'<span class="dot" style="margin-left:auto;color:var(--amber)"></span>':''}</button>`).join('')}`;
function dockContent(){return dock==='inspector'?'<div class="inspector-capture"><img src="current-interface-desktop.jpg" alt="Only the existing generated metatags inspector"></div>':`<div class="diag-row">${I('circle')}Numeriek maps to decimal<span class="grow"></span><span class="muted">Information</span></div><div class="diag-row">${I('circle')}Tekst maps to string<span class="grow"></span><span class="muted">Information</span></div>`;}
function model(){if(editorState==='loading')return loading();const draft=editorState==='draft',lost=editorState==='lost',bad=editorState==='error';return `<section class="workbench" id="workbench"><aside class="project" id="project"><div class="panel-title">Project<div class="flex">${B('','new-root','icon ghost','plus')}${B('','toggle-tree','icon ghost','tree')}</div></div><div class="search">${I('search')}<input placeholder="Find a root…" aria-label="Find a root in the design"></div><div class="tree">${treeGroup('servicetest.choice',[[rootName,'ObjectModel',true],['ibm','Invoerberichtmapping'],['keuzetest_A1790279010802','Service'],['leeg','Regelgroep'],['MoveTarget1790287481145','ObjectModel'],['MoveTarget1790287585892Z','ObjectModel'],['ubc','Uitvoerberichtmapping']])}${treeGroup('serviceEnBerichtTypesInAparteModellen.Berichten',[['Berichtuit_B1790279324981','Uitvoerberichtmapping'],['Invoer_spApart_spModel_A1790279324981','Invoerberichtmapping'],['Uitvoer_spApart_spModel','Uitvoerberichtmapping']])}${treeGroup('serviceEnBerichtTypesInAparteModellen.Regels',[['Regels apart model','Regelgroep']])}${treeGroup('serviceEnBerichtTypesInAparteModellen.Service',[['Regeltest','TestSet'],['serviceapartmodel','Service'],['ServiceTest','ServiceTestSet']])}${treeGroup('serviceEnBerichtTypesInAparteModellen.Gegevens',[['Gegevens apart model Remote','ObjectModel']])}</div><div class="project-footer">15 authorized roots · 6 models</div></aside><div class="workspace-editor">${correcting?`<div class="draft-context"><span class="pill">PR #${prId}</span><span>Correction draft from revision ${revision} · ${correctionSaved?'saved':'editable'}</span><span class="grow"></span>${B('Review & submit revision '+(revision+1),'review-correction','small',null,correctionSaved?'':'disabled')}</div>`:''}<div class="tabs">${B('','toggle-tree','icon ghost mobile-only','tree')}<button class="doc-tab">${I('file')}<span class="name">${rootName}</span>${draft||lost?'<span class="dot" style="color:var(--amber)"></span>':''}<span style="margin-left:auto">×</span></button><button class="doc-tab secondary">${I('file')}ubc<span style="margin-left:auto">×</span></button><span class="grow"></span>${B('','toggle-dock','icon ghost','panel')}</div><div class="editor-actions"><span class="root-label">${correcting?'PR correction draft':'ObjectModel'}</span><span class="divider"></span><span class="lock" style="color:${lost||bad?'var(--amber)':draft?'var(--green)':'var(--muted)'}">${I(draft?'lock':'unlock')}${draft?'Locked by you · this tab':lost?'Lock expired':bad?'Connection interrupted':'Read only'}</span><span class="grow"></span><span class="save-status muted" style="font-size:11px">${draft||lost?'Unsaved changes':'All changes saved'}</span><div class="flex undo-tools">${B('','undo','icon ghost','undo')}${B('','redo','icon ghost','redo')}</div>${B(draft?'Save':lost?'Resume draft':bad?'Reconnect':'Lock root',draft?'save':lost?'resume':bad?'reconnect':'lock','primary',draft?'check':'lock')}<div class="menu-wrap">${B('','more','icon ghost','more')}<div class="menu hidden" id="more-menu">${['Release lock','Lock model','Move root','Move content','Delete root','Reload workspace','Resume draft'].map(n=>B(n,'menu-action')).join('')}</div></div></div>${lost?`<div class="inline-alert">${I('circle')}Your local draft is preserved. Reacquire its lock and compare before saving.</div>`:bad?`<div class="inline-alert red">${I('circle')}Updates are paused. Reconnect before saving; your draft is preserved.</div>`:''}<div class="editing-center"><div class="canvas-area"><div class="native-window"><img class="native-surface" src="current-interface-desktop.jpg" alt="Captured, unchanged ALEF generated model editor"></div><span class="canvas-caption">Existing generated editor · illustrative editing state</span></div><section class="bottom-dock" id="bottom-dock"><div class="dock-tabs" role="tablist" aria-label="Editor tools"><button class="dock-tab ${dock==='inspector'?'active':''}" role="tab" aria-selected="${dock==='inspector'}" data-action="dock-inspector">Inspector</button><button class="dock-tab ${dock==='diagnostics'?'active':''}" role="tab" aria-selected="${dock==='diagnostics'}" data-action="dock-diagnostics">Diagnostics <span class="count">2</span></button><span class="grow"></span>${B('','toggle-dock','icon ghost','down')}</div><div class="dock-body" role="tabpanel" aria-label="${dock==='inspector'?'Generated inspector':'Diagnostics'}">${dockContent()}</div></section></div></div></section>`;}
function loading(){return `<div style="background:#f7f9f6;display:flex;flex:1"><section class="loading-panel"><span class="pill">Shared workspace</span><h2>Opening your workspace</h2><p>Loading the complete model view you can access. Editing opens after initialization finishes.</p><div class="progress-track" style="height:5px;margin-top:24px"><span style="width:73%"></span></div><div class="flex hint"><span>Initializing models</span><span class="grow"></span><strong>11 of 15 roots</strong></div><div class="load-stage">Authenticate & authorize<strong>Complete</strong></div><div class="load-stage">Transfer snapshot<strong>Complete</strong></div><div class="load-stage">Initialize models<strong>73%</strong></div><div class="load-stage pending">Resolve references<span>Pending</span></div><div style="text-align:right;margin-top:20px">${B('Cancel','cancel-load','small')}</div></section></div>`;}
function steps(active){return `<div class="flow-steps"><span class="${active===1?'active':''}">1. Review changes</span>${I('chevron')}<span class="${active===2?'active':''}">2. Pull request</span>${I('chevron')}<span class="${active===3?'active':''}">3. Create release</span>${I('chevron')}<span class="${active===4?'active':''}">4. Deploy</span></div>`;}
function files(){return `<aside class="changed-files"><div class="upper">Changed models · 3</div>${[['gegevens','Gegevensmodel','de naam / de voornaam'],['service','serviceapartmodel','reference updated'],['test','ServiceTest','expected value updated']].map(([key,name,desc])=>B(`<span class="type-icon">${name[0]}</span><span>${name}<small>${desc}</small></span><span class="file-letter">M</span>`,'select-file',selectedFile===key?'selected':'','',`data-file="${key}"`)).join('')}</aside>`;}
function diffLines(kind){const historical=selectedRevision<revision;const title=kind==='changes'&&correcting?'Correction draft':kind==='changes'?'Saved workspace':`Revision ${selectedRevision} · read only`;const old=selectedFile==='gegevens'?['Objecttype de naam','  de bijnaam   Tekst;','  de initialen Tekst;','  de voornaam  Tekst;']:selectedFile==='service'?['Service serviceapartmodel','  uitvoer naam','  verwijst naar de voornaam']:['ServiceTest','  invoer persoon','  verwacht voornaam = "Jan"'];const fresh=old.slice();fresh[fresh.length-1]=selectedFile==='gegevens'?'  de roepnaam  Tekst;':selectedFile==='service'?'  verwijst naar de roepnaam':'  verwacht roepnaam = "Jan"';const cols=[[(kind==='changes'&&correcting?'Submitted revision '+revision:'Baseline · v1.3.0'),old,false],[title,fresh,true]];return `<div class="diff-top">${I('file')}<strong>${selectedFile==='gegevens'?'Gegevensmodel':selectedFile==='service'?'serviceapartmodel':'ServiceTest'}</strong><span class="muted">${selectedFile==='gegevens'?'de naam':''}</span><span class="grow"></span><span class="pill neutral">Modified</span>${kind!=='changes'?I('lock'):''}</div><div class="line-diff">${cols.map(([label,lines,right])=>`<div><div class="diff-title">${label}</div>${lines.map((line,i)=>`<div class="number-line ${i===lines.length-1?(right?'add':'remove'):''}"><span class="ln">${i+1}</span><code>${i===lines.length-1?(right?'+ ':'− '):'  '}${escapeText(line)}</code></div>`).join('')}<div class="diff-space"></div></div>`).join('')}</div>${kind!=='changes'?`<div class="inline-thread"><div class="flex"><span class="avatar">RL</span><strong>reviewer Local</strong><small>on revision ${historical?selectedRevision:1}</small><span class="grow"></span><span class="pill ${threadResolved?'':'warn'}">${threadResolved?'Resolved':'Discussion'}</span></div><p>Please also update the service reference and the matching Testspraak expectation.</p>${selectedRevision>1?'<div style="border-left:2px solid var(--line);padding-left:12px"><strong>author Local</strong><p>Both are included in revision 2. The earlier snapshot is retained.</p></div>':''}<div class="flex">${B('Reply','reply','small ghost')}${B(threadResolved?'Reopen discussion':'Resolve discussion','resolve','small ghost')}<span class="grow"></span><small>Thread stays linked to its original revision.</small></div></div>`:''}`;}
function changes(){return `<section class="page">${steps(1)}<div class="page-heading"><div class="grow"><h1>${correcting?'Requested changes':'Changes'}</h1><p>${correcting?`Correction draft for PR #${prId}, based on its revision ${revision}.`:'Inspect the saved workspace before opening a pull request.'}</p></div>${B(correcting?'Submit revision '+(revision+1):'Create pull request',correcting?'submit-revision':'create-pr','primary','arrow')}</div><div class="compare-bar"><span class="muted">Compare</span><select aria-label="Comparison baseline"><option>${correcting?'PR #'+prId+' · revision '+revision:'Last release · v1.3.0'}</option></select>${I('arrow')}<strong>${correcting?'Saved correction draft':'Saved workspace'}</strong><code>${correcting?'draft':'4ae7b2c'}</code><span class="grow"></span><span class="pill neutral">3 models changed</span></div><div class="subtle-banner">${I('circle')}${correcting?'Submitting creates a new frozen revision in this pull request. Earlier revisions and comments remain available.':'Only the selected saved revision is submitted. Unsaved local edits are excluded.'}</div><div class="diff-workspace">${files()}<div class="diff-main">${diffLines('changes')}<div class="immutable-strip">${I('file')}Complete workspace snapshot · model changes + resources + pinned dependencies</div></div></div></section>`;}
function reviewState(){if(selectedRevision<revision)return {label:'Earlier revision',style:'neutral'};return {label:({OPEN:'Open',CHANGES_REQUESTED:'Changes requested',APPROVED:'Approved',RELEASED:'Released',DECLINED:'Declined'})[prState],style:prState==='CHANGES_REQUESTED'?'warn':prState==='DECLINED'?'danger':prState==='OPEN'?'neutral':''};}
function pullRequest(){const snapshot=snapshots[selectedRevision],status=reviewState(),old=selectedRevision<revision;return `<section class="page">${steps(2)}<div class="breadcrumbs">Pull requests ${I('chevron')} #${prId}</div><div class="page-heading pr-title"><div class="grow"><div class="flex" style="margin-bottom:7px"><h1 style="margin:0">Gegevensmodel update</h1><span class="pill ${status.style}">${status.label}</span></div><div class="pr-meta"><span>author Local opened PR #${prId}</span><span>·</span><code>revision ${selectedRevision}</code>${I('arrow')}<span>release from approved snapshot</span></div></div><div class="page-actions">${prState==='CHANGES_REQUESTED'&&!old?B('Edit requested version','edit-requested','primary','file'):''}${prState==='APPROVED'&&!old?B('Create release','create-release','primary','arrow'):''}${prState==='RELEASED'&&!old?B('View release','view-release','primary','arrow'):''}${B('All pull requests','pr-list','small')}</div></div>${prState==='CHANGES_REQUESTED'&&!old?`<div class="subtle-banner warn">${I('circle')}Changes requested. Open a correction draft from revision ${revision}, then resubmit it to this pull request. The reviewed snapshot stays unchanged.</div>`:''}<div class="pr-tabs" role="tablist" aria-label="Pull request sections">${[['overview','Overview'],['diff','Diff'],['revisions','Revisions'],['checks','Checks']].map(([key,label])=>B(label+(key==='revisions'?` <span class="count">${revision}</span>`:''),'pr-tab',prTab===key?'active':'','',`data-tab="${key}" role="tab" aria-selected="${prTab===key}"`)).join('')}<span class="grow"></span><select class="revision-select" aria-label="Review revision">${Object.keys(snapshots).map(Number).sort((a,b)=>b-a).map(n=>`<option value="${n}" ${n===selectedRevision?'selected':''}>Revision ${n}${n===revision?' · latest':' · earlier'}</option>`).join('')}</select></div><div class="pr-layout"><div>${prContent()}<div class="immutable-strip" style="border:1px solid var(--line);margin-top:14px;border-radius:5px">${I('lock')}Revision ${selectedRevision} is immutable <span class="grow"></span><code>${snapshot.hash}</code><span>·</span><code>sha256:${snapshot.digest}</code></div></div><aside class="review-rail stack"><article class="card"><div class="card-head">Reviewers<span class="grow"></span><span class="pill neutral">${['APPROVED','RELEASED'].includes(prState)&&!old?'1':'0'} / 1</span></div><div class="card-body"><div class="flex"><span class="avatar">RL</span><div><strong style="font-size:12px">reviewer Local</strong><div class="hint">Independent reviewer</div></div></div><div class="check-line">${I('check')}All roots accessible</div><div class="check-line">${I('check')}Not an author or contributor</div><div class="check-line">${I('check')}Native validation passed</div><p>Decision applies only to revision ${selectedRevision} and its exact package.</p>${!old&&prState==='OPEN'?`<label class="hint" for="review-reason">Review summary</label><textarea class="review-reason" id="review-reason" placeholder="Add your review feedback…"></textarea><div class="decision-actions">${B('Approve revision '+revision,'approve','primary','check')}${B('Request changes','request-changes')}${B('Decline','decline','ghost small')}</div>`:old?'<div class="subtle-banner">Read only. Select the latest revision to review.</div>':prState==='CHANGES_REQUESTED'?`<span class="pill warn">Awaiting author updates</span><p>Previous approval does not carry forward. The next revision needs a fresh review.</p>`:prState==='APPROVED'||prState==='RELEASED'?`<span class="pill">${I('check')}Approved exact snapshot</span><p>${prState==='RELEASED'?'Release v1.4.0 retains this package unchanged.':'Ready to create an immutable release without rebuilding its package.'}</p>`:'<p>This pull request is closed.</p>'}</div></article><article class="card compact-card"><h3>Pull request details</h3><div class="facts"><div><span class="muted">Baseline</span><strong>v1.3.0 · 73fd446</strong></div><div><span class="muted">Scope</span><strong>Complete workspace</strong></div><div><span class="muted">Updated</span><strong>Today, 10:42</strong></div><div><span class="muted">Package</span><strong>Retained & checksummed</strong></div></div><p class="revision-note">Revisions and checksums are illustrative in this design.</p></article></aside></div></section>`;}
function prContent(){if(prTab==='diff')return `<div class="diff-workspace">${files()}<div class="diff-main">${diffLines('review')}</div></div>`;if(prTab==='overview')return `<article class="pr-overview"><h2>Description</h2><p>Update the name model and its service references. Adjust the ServiceTest expectation to match.</p><h2 style="margin-top:26px">Activity</h2><div class="timeline"><div class="timeline-row"><strong>Revision ${revision} submitted</strong><small>Fresh validation and independent review required.</small></div><div class="timeline-row"><strong>Changes requested on revision 1</strong><small>Service reference and expected value needed an update.</small></div><div class="timeline-row"><strong>Pull request opened</strong><small>author Local · fixed source snapshot</small></div></div></article>`;if(prTab==='checks')return `<article class="pr-overview"><h2>Checks for revision ${selectedRevision}</h2><div class="check-line">${I('check')}Native MPS validation passed</div><div class="check-line">${I('check')}1 Testspraak test passed</div><div class="check-line">${I('check')}Package sealed and retained</div><div class="check-line">${I('check')}Persisted source unchanged</div><p class="hint">2 informational diagnostics: Numeriek maps to decimal; Tekst maps to string.</p><p class="hint">Checks are attached to this revision. They cannot be reused for a changed snapshot.</p></article>`;return `<article class="card"><div class="card-head">Immutable revision history</div>${Object.values(snapshots).sort((a,b)=>b.revision-a.revision).map(s=>`<div class="release-row"><span class="pill neutral">r${s.revision}</span><div class="grow"><strong style="font-size:13px">${s.status}</strong><p><code>${s.hash} · sha256:${s.digest}</code></p></div>${B('View diff','view-revision','small','','data-revision="'+s.revision+'"')}</div>`).join('')}<div class="immutable-strip">A correction creates the next revision. Existing snapshots, decisions and comments are retained.</div></article>`;}
function releaseList(){return `<section class="page">${steps(3)}<div class="page-heading"><div class="grow"><h1>Releases</h1><p>Immutable packages created from an approved pull-request revision.</p></div>${B('Open pull request','open-pr','small','arrow')}</div><div class="subtle-banner">${I('lock')}Release creation names the approved package; it does not rebuild it or include later workspace edits.</div><article class="card">${released?`<div class="release-row"><span class="platform-icon">${I('file')}</span><div class="grow"><h2>v1.4.0 <span class="pill">Released</span></h2><p>Gegevensmodel update · PR #${prId}, revision ${revision}</p><code>sha256:${snapshots[revision].digest}</code></div>${B('Deploy to environments','go-environments','primary','arrow')}</div>`:`<div class="release-row"><div class="grow"><h2>Gegevensmodel update</h2><p>PR #${prId} · ${prState==='APPROVED'?'approved and ready to release':'requires approval of the latest revision'}</p></div>${B(prState==='APPROVED'?'Create release':'Review pull request',prState==='APPROVED'?'create-release':'open-pr','primary')}</div>`}<div class="release-row"><span class="platform-icon">${I('file')}</span><div class="grow"><h2>v1.3.0 <span class="pill neutral">Previous release</span></h2><p>Retained source package · approved independently</p><code>sha256:f0b39be8…079b</code></div>${B('Package details','package-details','small')}${B('Deploy / rollback','rollback','small')}</div></article><p class="hint" style="margin-top:18px">Revoking approval blocks new delivery or rollback jobs. It does not rewrite a release or its existing history.</p></section>`;}
function envRows(type){return environments.filter(e=>e.type===type).map((e,index)=>`<tr><td><span class="env-name">${I('server')}${escapeText(e.name)}</span><small>Configuration ${e.config} · durable stub</small></td><td><strong>${e.version==='—'?'None':'v'+e.version}</strong><small><code>${e.version==='1.4.0'?(released?snapshots[revision].digest:'9c1f72b4…6f08'):e.version==='—'?'No installed package':'f0b39be8…079b'}</code></small></td><td><span class="pill ${e.status==='Succeeded'?'':['Blocked','Uncertain'].includes(e.status)?'warn':'neutral'}">${e.status}</span>${e.status==='Running'?'<div class="progress-track"><span style="width:67%"></span></div><small>Verifying package · 67%</small>':''}</td><td class="env-gates">${type==='production'?'<span class="gate-pass">✓ Integration</span><br><span class="gate-wait">○ Acceptance + environment approval</span>':['Integration','Acceptance'].includes(e.name)?'Required for Production EU':'Optional for production'}</td><td><span class="pill warn">SIMULATED</span></td><td>${B(e.status==='Running'?'View progress':e.status==='Blocked'?'View gates':e.status==='Uncertain'?'Reconcile':'Deploy…',e.status==='Running'?'delivery':e.status==='Blocked'?'gates':e.status==='Uncertain'?'reconcile':'deploy-env','small','','data-environment="'+escapeText(e.name)+'"')}${B('','configure-env','icon ghost','settings','data-environment="'+escapeText(e.name)+'"')}</td></tr>`).join('');}
function environmentPage(){const count=environments.filter(e=>e.type==='test').length;return `<section class="page">${steps(4)}<div class="page-heading"><div class="grow"><h1>Environments</h1><p>Deploy the same released package to any authorized target. Each environment has its own history and gates.</p></div><div class="page-actions">${B('Add environment','add-environment','small','plus')}${B('Deploy release','deploy-env','primary','arrow')}</div></div><div class="simulation">${I('circle')}<strong>Simulation only</strong><span>All listed targets are durable stubs. No ALEF services execute here.</span></div><div class="env-controls"><div class="segmented" aria-label="Environment type filter">${[['all','All environments'],['test','Test'],['production','Production']].map(([value,label])=>B(label,'env-filter',envFilter===value?'active':'','','data-filter="'+value+'"')).join('')}</div><span class="grow"></span><label class="hint" for="env-release">Status for release</label><select id="env-release"><option>v1.4.0 · Gegevensmodel update</option><option>v1.3.0 · Previous release</option></select></div><div class="env-stats"><span><strong>${count}</strong> test environments</span><span><strong>${environments.filter(e=>e.type==='production').length}</strong> production</span><span class="grow"></span><span class="hint">Illustrative deployed release</span></div>${['test','production'].filter(type=>envFilter==='all'||envFilter===type).map(type=>`<section class="env-section"><div class="env-section-head">${type==='test'?'Test environments':'Production environments'}<span class="count">${environments.filter(e=>e.type===type).length}</span><span class="grow"></span><span class="muted">${type==='test'?'Run independently · prerequisites are configurable':'Promote the exact package that passed the selected gates'}</span></div><div class="environment-table"><table><thead><tr><th>Environment</th><th>Last confirmed release</th><th>Delivery for v1.4.0</th><th>Promotion gates</th><th>Adapter</th><th></th></tr></thead><tbody>${envRows(type)}</tbody></table></div></section>`).join('')}<article class="card"><div class="card-head">Recent deployments<span class="grow"></span><span class="hint">Each target is tracked separately</span></div><div class="history-wrap"><table class="history"><thead><tr><th>Release / environment</th><th>Purpose</th><th>Status</th><th>Operation</th><th></th></tr></thead><tbody><tr><td>v1.4.0 → Regression<small>SIMULATED · exact retained package</small></td><td>Deploy</td><td><span class="pill neutral">Running</span></td><td><code>op_028</code></td><td>${B('Details','delivery','small')}</td></tr><tr><td>v1.4.0 → Acceptance<small>SIMULATED · no confirmed installation</small></td><td>Deploy</td><td><span class="pill warn">Outcome uncertain</span></td><td><code>op_027</code></td><td>${B('Reconcile original','reconcile','small')}</td></tr></tbody></table></div></article></section>`;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.add('hidden'),4500);}
function closeModal(){document.querySelector('#modal-host').innerHTML='';}
function modal(title,body,actionLabel='Close preview',action='close-modal'){document.querySelector('#modal-host').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${escapeText(title)}"><article class="card"><div class="card-head">${title}<span class="grow"></span>${B('','close-modal','icon ghost','close')}</div><div class="card-body">${body}<div class="flex" style="justify-content:flex-end;margin-top:20px">${B(actionLabel,action,'primary')}</div></div></article></div>`;iconLabels();document.querySelector('.modal button').focus();}
function correction(){correcting=true;correctionSaved=false;editorState='draft';go('model');toast('Design preview: editable copy of PR revision '+revision+'. The reviewed snapshot remains frozen.');}
function createReleaseDialog(){if(prState!=='APPROVED'){toast('The latest revision needs independent approval first.');return;}modal('Create release from PR #'+prId,`<label for="release-name">Release version</label><input id="release-name" value="1.4.0" readonly><p>Approved revision ${revision} · <code>${snapshots[revision].hash}</code></p><div class="selection-box">Immutable package <code>sha256:${snapshots[revision].digest}</code></div><p>No rebuild. No later workspace changes. This release names the exact approved package.</p><p class="hint">Design preview only; no release is created in ALEF.</p>`,'Create release · preview','confirm-release');}
function handle(action,button){if(action==='toggle-tree'){document.querySelector(innerWidth<=800?'#project':'#workbench').classList.toggle(innerWidth<=800?'drawer-open':'no-tree');return;}if(action==='toggle-dock'){document.querySelector('#bottom-dock').classList.toggle('closed');return;}if(action==='dock-inspector'||action==='dock-diagnostics'){dock=action==='dock-inspector'?'inspector':'diagnostics';render();return;}if(action==='more'){document.querySelector('#more-menu').classList.toggle('hidden');return;}if(action==='save'){editorState='saved';if(correcting)correctionSaved=true;render();toast('Saved-state preview only. No model data was written.');return;}if(['lock','resume','reconnect'].includes(action)){editorState='draft';render();return;}if(action==='cancel-load'){editorState='saved';render();return;}if(action==='select-file'){selectedFile=button.dataset.file;render();return;}if(action==='pr-tab'){prTab=button.dataset.tab;render();return;}if(action==='view-revision'){selectedRevision=Number(button.dataset.revision);prTab='diff';render();return;}if(action==='create-pr'){modal('Create pull request',`<label for="pr-title">Title</label><input id="pr-title" value="Gegevensmodel update"><label for="pr-description">Description</label><textarea id="pr-description" class="comment-input">Update the model, service references and matching tests.</textarea><label for="pr-reviewer">Reviewer</label><select id="pr-reviewer"><option>reviewer Local · independent</option></select><div class="selection-box">Source: saved workspace <code>4ae7b2c</code><br>Baseline: release v1.3.0 <code>73fd446</code></div><p>The complete snapshot becomes read only in the pull request. Local unsaved edits are excluded.</p>`,'Create pull request · preview','confirm-pr');return;}if(action==='confirm-pr'){prId=19;revision=1;selectedRevision=1;Object.keys(snapshots).forEach(k=>delete snapshots[k]);snapshots[1]={revision:1,hash:'4ae7b2c',digest:'9c1f72b4…6f08',status:'In review'};prState='OPEN';prTab='diff';correcting=false;released=false;closeModal();go('pulls');return;}if(action==='request-changes'){const reason=document.querySelector('#review-reason')?.value.trim();modal('Request changes to revision '+revision,`<label for="change-request">Feedback for the author</label><textarea id="change-request" class="comment-input" rows="4">${escapeText(reason||'Please update the related service reference and verify the Testspraak expectation.')}</textarea><p>The author can open a correction draft from this exact version and submit a new revision to the same pull request.</p><p>Revision ${revision}, its package and review history stay unchanged.</p>`,'Request changes · preview','confirm-changes');return;}if(action==='confirm-changes'){prState='CHANGES_REQUESTED';snapshots[revision].status='Changes requested';closeModal();render();return;}if(action==='edit-requested'){correction();return;}if(action==='review-correction'){go('changes');return;}if(action==='submit-revision'){if(!correcting||!correctionSaved){toast('Save the correction draft before submitting a revision.');return;}const n=revision+1;modal('Submit revision '+n,`<p>Freeze the saved correction draft as revision ${n} of PR #${prId}.</p><div class="selection-box">Revision ${revision}: retained, read only<br>Revision ${n}: new snapshot, validation and review</div><p>Approvals do not transfer. Existing comments remain linked to their original revision.</p>`,'Submit new revision · preview','confirm-revision');return;}if(action==='confirm-revision'){revision++;selectedRevision=revision;snapshots[revision]={revision,hash:'8bc4d'+revision+'a',digest:'c93a40'+revision+'d…201a',status:'In review'};prState='OPEN';correcting=false;correctionSaved=false;prTab='diff';closeModal();go('pulls');return;}if(action==='approve'){if(selectedRevision!==revision||prState!=='OPEN')return;prState='APPROVED';snapshots[revision].status='Approved';render();toast('Design preview: approval is bound to the selected revision and exact package.');return;}if(action==='decline'){prState='DECLINED';snapshots[revision].status='Declined';render();return;}if(action==='create-release'){createReleaseDialog();return;}if(action==='confirm-release'){released=true;prState='RELEASED';snapshots[revision].status='Released as v1.4.0';closeModal();go('releases');return;}if(action==='view-release'){go('releases');return;}if(action==='open-pr'){selectedRevision=revision;go('pulls');return;}if(action==='go-environments'){go('deployments');return;}if(action==='resolve'){threadResolved=!threadResolved;render();return;}if(action==='reply'){modal('Reply to review thread','<textarea class="comment-input" rows="4" placeholder="Write a reply…"></textarea><p>Comments are anchored to a specific revision and node/change.</p>','Close preview');return;}if(action==='pr-list'){modal('Pull requests',`<div class="release-row"><div class="grow"><strong>#${prId} · Gegevensmodel update</strong><p>${reviewState().label} · latest revision ${revision}</p></div></div><p>Filter by open, changes requested, approved, released or declined.</p>`);return;}if(action==='env-filter'){envFilter=button.dataset.filter;render();return;}if(action==='add-environment'){modal('Add environment',`<label for="environment-name">Name</label><input id="environment-name" placeholder="For example: Performance test"><label for="environment-type">Type</label><select id="environment-type"><option value="test">Test</option><option value="production">Production</option></select><label>Adapter</label><input value="Durable stub · SIMULATED" readonly><p>Each environment has its own configuration, permissions, deployment history and prerequisites.</p>`,'Add environment · preview','confirm-environment');return;}if(action==='confirm-environment'){const name=document.querySelector('#environment-name').value.trim();if(!name){toast('Enter an environment name.');return;}environments.push({name,type:document.querySelector('#environment-type').value,version:'—',status:'Not deployed',config:1});closeModal();envFilter='all';render();return;}if(action==='configure-env'){modal('Configure '+escapeText(button.dataset.environment),`<label>Adapter</label><input value="Durable stub · SIMULATED" readonly><label>Prerequisite environments</label><div class="selection-box">${environments.filter(e=>e.type==='test'&&e.name!==button.dataset.environment).map(e=>`<label><input type="checkbox" ${e.name!=='Regression'?'checked':''}>${escapeText(e.name)}</label>`).join('')}<small>Every selected environment must have succeeded with the same package.</small></div><div class="selection-box"><label><input type="checkbox" checked>Require independent environment approval</label></div><p>Changes create a new configuration version. Cyclic prerequisite relationships are rejected.</p>`);return;}if(action==='deploy-env'){modal('Deploy release · simulation',`<span class="pill warn">SIMULATED</span><label style="margin-top:15px">Released package</label><select><option>v1.4.0 · approved PR snapshot</option><option>v1.3.0 · retained previous release</option></select><label>Target environments</label><div class="selection-box">${environments.map(e=>`<label><input type="checkbox" ${e.type==='production'?'disabled':e.name===button.dataset.environment?'checked':''}>${escapeText(e.name)}${e.type==='production'?' · prerequisites pending':''}</label>`).join('')}</div><p>Each target gets an independent job. All receive the same immutable package. Authorization and approval are checked again at dispatch.</p>`,'Close preview');return;}if(action==='gates'){modal('Production EU · promotion gates',`<div class="check-line">${I('check')}Integration: v1.4.0, matching package, succeeded</div><div class="check-line">${I('clock')}Acceptance: no confirmed successful delivery</div><div class="check-line">${I('lock')}Independent environment approval required</div><p>Regression is optional for this target. The required test environments are configurable per production environment.</p><span class="pill warn">SIMULATED</span>`);return;}if(action==='delivery'||action==='reconcile'){modal(action==='reconcile'?'Reconcile original operation':'Deployment progress',`<span class="pill warn">SIMULATED</span><p>${action==='reconcile'?'Look up op_027 on Acceptance before retrying. An uncertain outcome must not create a duplicate submission.':'Regression · v1.4.0 · verifying package checksums'}</p><div class="progress-track"><span style="width:67%"></span></div><p>No ALEF services are executed.</p>${B('Cancel delivery','close-modal','small')}`);return;}if(action==='rollback'){modal('Governed rollback',`<p>Select a previously delivered, retained, approved release and one or more eligible environments.</p><div class="selection-box">v1.3.0 · <code>f0b39be8…079b</code></div><p>Rollback creates separate delivery jobs and obeys each target's gates.</p><span class="pill warn">SIMULATED</span>`);return;}if(action==='close-modal'){closeModal();return;}if(action==='new-root'){modal('Create root','<label>Root type</label><select><option>ObjectModel</option><option>Regelgroep</option><option>Service</option><option>ServiceTestSet</option></select><p>The generated root editor and model/root lease rules remain unchanged.</p>');return;}toast('Design control only. No application data was changed.');}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return;}const b=e.target.closest('[data-action]');if(b)handle(b.dataset.action,b);});
document.querySelector('#state-preview').addEventListener('change',e=>{editorState=e.target.value;render();});
document.addEventListener('change',e=>{if(e.target.matches('[aria-label="Review revision"]')){selectedRevision=Number(e.target.value);render();}if(e.target.id==='env-release')toast('Illustrative release selector; target rows show the v1.4.0 scenario.');});
document.addEventListener('input',e=>{if(e.target.matches('.search input'))document.querySelectorAll('.tree button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.querySelectorAll('.drawer-open').forEach(x=>x.classList.remove('drawer-open'));document.querySelector('#more-menu')?.classList.add('hidden');}});
const initial=location.hash.slice(1);if(['model','changes','pulls','releases','deployments'].includes(initial))view=initial;render();
